     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	
     9	/**
    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    12	 * (half-even) at every step.
    13	 */
    14	public final class PriceCalculator {
    15	
    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    17	
    18	    private final RatePlanStrategies strategies;
    19	
    20	    public PriceCalculator() {
    21	        this.strategies = new RatePlanStrategies(this);
    22	    }
    23	
    24	    public Price calculate(
    25	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    26	        int nights = (int) checkIn.datesUntil(checkOut).count();
    27	        RatePlanStrategy strategy = strategies.get(ratePlan);
    28	        strategy.validate(room, checkIn, checkOut, nights, companyCode);
    29	        return strategy.calculatePrice(room, checkIn, checkOut, nights, companyCode);
    30	    }
    31	
    32	    public BigDecimal refund(RatePlan ratePlan, BigDecimal amountPaid) {
    33	        return strategies.get(ratePlan).calculateRefund(amountPaid);
    34	    }
    35	
    36	    BigDecimal nightPrice(Room room, LocalDate night) {
    37	        BigDecimal nightlyRate = room.nightlyRate();
    38	        if (isHighSeason(night)) {
    39	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    40	        }
    41	        return cents(nightlyRate);
    42	    }
    43	
    44	    /** High season: from December 15 to the end of February, and the whole of July. */
    45	    static boolean isHighSeason(LocalDate date) {
    46	        Month month = date.getMonth();
    47	        return month == Month.JANUARY
    48	                || month == Month.FEBRUARY
    49	                || month == Month.JULY
    50	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    51	    }
    52	
    53	    static BigDecimal cents(BigDecimal value) {
    54	        return value.setScale(2, RoundingMode.HALF_EVEN);
    55	    }
    56	}
     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        Room room = rooms.find(request.roomNumber())
    35	                .orElseThrow(() -> new HotelException(
    36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    37	        if (request.guests() > room.capacity()) {
    38	            throw new HotelException(
    39	                    ErrorCode.CAPACITY_EXCEEDED,
    40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    41	        }
    42	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    43	            throw new HotelException(
    44	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    45	        }
    46	        Price price = priceCalculator.calculate(
    47	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
    48	        return store.add(request, price);
    49	    }
    50	
    51	    public Reservation find(long reservationId) {
    52	        return store.find(reservationId)
    53	                .orElseThrow(() -> new HotelException(
    54	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    55	    }
    56	
    57	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    58	    public synchronized Reservation confirm(long reservationId) {
    59	        Reservation reservation = find(reservationId);
    60	        if (reservation.status() != ReservationStatus.PENDING) {
    61	            throw notAllowed(reservation, "confirm");
    62	        }
    63	        reservation.confirmPayment();
    64	        store.update(reservation);
    65	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    66	        emailSender.send(
    67	                reservation.guest().email(),
    68	                "Reserva confirmada - " + HOTEL_NAME,
    69	                confirmationEmailBody(reservation, receipt));
    70	        return reservation;
    71	    }
    72	
    73	    /**
    74	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    75	     * reservation was never paid, so nothing comes back).
    76	     */
    77	    public synchronized Reservation cancel(long reservationId) {
    78	        Reservation reservation = find(reservationId);
    79	        if (reservation.status() != ReservationStatus.PENDING
    80	                && reservation.status() != ReservationStatus.CONFIRMED) {
    81	            throw notAllowed(reservation, "cancel");
    82	        }
    83	        BigDecimal refund = priceCalculator.refund(reservation.ratePlan(), reservation.amountPaid());
    84	        reservation.cancel(refund);
    85	        store.update(reservation);
    86	        return reservation;
    87	    }
    88	
    89	    public synchronized Reservation checkIn(long reservationId) {
    90	        Reservation reservation = find(reservationId);
    91	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    92	            throw notAllowed(reservation, "check in");
    93	        }
    94	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    95	        store.update(reservation);
    96	        return reservation;
    97	    }
    98	
    99	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   100	    public synchronized ReservationReceipt checkOut(long reservationId) {
   101	        Reservation reservation = find(reservationId);
   102	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   103	            throw notAllowed(reservation, "check out");
   104	        }
   105	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   106	        store.update(reservation);
   107	        return new ReservationReceipt(reservation, roomOf(reservation));
   108	    }
   109	
   110	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   111	    public ReservationReceipt receiptCopy(long reservationId) {
   112	        Reservation reservation = find(reservationId);
   113	        if (!reservation.isPaid()) {
   114	            throw notAllowed(reservation, "issue a receipt for");
   115	        }
   116	        return new ReservationReceipt(reservation, roomOf(reservation));
   117	    }
   118	
   119	    private Room roomOf(Reservation reservation) {
   120	        return rooms.find(reservation.roomNumber()).orElseThrow();
   121	    }
   122	
   123	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   124	        return "Olá, " + reservation.guest().name() + "!\n\n"
   125	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   126	                + receipt.text() + "\n"
   127	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   128	                + "Até breve!\n";
   129	    }
   130	
   131	    private static HotelException notAllowed(Reservation reservation, String operation) {
   132	        return new HotelException(
   133	                ErrorCode.OPERATION_NOT_ALLOWED,
   134	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   135	    }
   136	}
